import { springChallenge as s } from './challenge-helpers.js';

export const springChallenges = [
s(12, 'Medium', 'Route notifications through injected strategies',
  'Implement a Spring-managed NotificationRouter that indexes all injected Channel beans by their unique nonblank name. Fail startup for duplicate names. send(name, message) must delegate to the selected channel and reject unknown names. Do not construct concrete channels manually. Assume thread-safe channel implementations and non-null messages.',
  'email and sms beans are routed by name. Duplicate email beans fail construction; unknown push is rejected.',
  'import java.util.*;\nimport org.springframework.stereotype.Service;\n\ninterface Channel { String name(); void send(String message); }\n@Service\nclass NotificationRouter {\n    NotificationRouter(List<Channel> channels) { /* TODO */ }\n    void send(String name, String message) { /* TODO */ }\n}',
  'import java.util.*;\nimport org.springframework.stereotype.Service;\n\ninterface Channel { String name(); void send(String message); }\n@Service\nclass NotificationRouter {\n    private final Map<String, Channel> channels;\n    NotificationRouter(List<Channel> candidates) {\n        Map<String, Channel> index = new HashMap<>();\n        for (Channel channel : candidates) {\n            String name = Objects.requireNonNull(channel.name());\n            if (name.isBlank() || index.putIfAbsent(name, channel) != null)\n                throw new IllegalArgumentException("Invalid or duplicate channel: " + name);\n        }\n        channels = Map.copyOf(index);\n    }\n    void send(String name, String message) {\n        Channel channel = channels.get(name);\n        if (channel == null) throw new IllegalArgumentException("Unknown channel");\n        channel.send(message);\n    }\n}',
  'Inject the strategy list, build a validated immutable index once, and delegate without concrete-type switches.',
  'Context: spring-boot-starter, with Channel implementation beans supplied by the application. Check duplicate registration, unknown channels, and delegation to exactly one strategy.'),
s(13, 'Medium', 'Create a validated customer REST endpoint',
  'Implement POST /customers using Jakarta validation. Require a nonblank name and syntactically valid nonblank email. Call the supplied CustomerService only for valid requests and return 201 with a Location header /customers/{id} and a CustomerDto. Do not return an entity. Assume service creation succeeds and returns a unique ID.',
  'Valid JSON -> 201, Location: /customers/42, DTO body. Blank name or invalid email -> 400 without calling the service.',
  'import jakarta.validation.Valid;\nimport jakarta.validation.constraints.*;\nimport org.springframework.web.bind.annotation.*;\nimport org.springframework.http.ResponseEntity;\n\nrecord CreateCustomer(String name, String email) {}\nrecord CustomerDto(long id, String name, String email) {}\ninterface CustomerService { CustomerDto create(String name, String email); }\n@RestController\nclass CustomerController {\n    private final CustomerService service;\n    CustomerController(CustomerService service) { this.service = service; }\n    // TODO add POST endpoint and DTO constraints\n}',
  'import java.net.URI;\nimport jakarta.validation.Valid;\nimport jakarta.validation.constraints.*;\nimport org.springframework.web.bind.annotation.*;\nimport org.springframework.http.ResponseEntity;\n\nrecord CreateCustomer(@NotBlank String name, @NotBlank @Email String email) {}\nrecord CustomerDto(long id, String name, String email) {}\ninterface CustomerService { CustomerDto create(String name, String email); }\n@RestController\nclass CustomerController {\n    private final CustomerService service;\n    CustomerController(CustomerService service) { this.service = service; }\n    @PostMapping("/customers")\n    ResponseEntity<CustomerDto> create(@Valid @RequestBody CreateCustomer request) {\n        CustomerDto customer = service.create(request.name(), request.email());\n        return ResponseEntity.created(URI.create("/customers/" + customer.id())).body(customer);\n    }\n}',
  'Constrain the request record, activate body validation, delegate, and build an explicit created response.',
  'Context: spring-boot-starter-web and spring-boot-starter-validation, plus a CustomerService bean. Check malformed JSON, blank email, and invalid name. @Email alone does not require nonblank input.'),
s(13, 'Medium', 'Return consistent validation problem details',
  'Implement RestControllerAdvice for MethodArgumentNotValidException. Return HTTP 400 with RFC ProblemDetail title "Invalid request" and a fields property containing distinct sorted invalid field names. Do not echo rejected values or internal exception messages.',
  'Invalid email and name -> status 400, title Invalid request, fields [email, name].',
  'import org.springframework.web.bind.annotation.*;\nimport org.springframework.web.bind.MethodArgumentNotValidException;\nimport org.springframework.http.*;\n\n@RestControllerAdvice\nclass ValidationAdvice {\n    // TODO handle invalid request body validation\n}',
  'import org.springframework.web.bind.annotation.*;\nimport org.springframework.web.bind.MethodArgumentNotValidException;\nimport org.springframework.http.*;\n\n@RestControllerAdvice\nclass ValidationAdvice {\n    @ExceptionHandler(MethodArgumentNotValidException.class)\n    ResponseEntity<ProblemDetail> invalid(MethodArgumentNotValidException failure) {\n        ProblemDetail problem = ProblemDetail.forStatus(HttpStatus.BAD_REQUEST);\n        problem.setTitle("Invalid request");\n        problem.setDetail("One or more fields are invalid.");\n        problem.setProperty("fields", failure.getBindingResult().getFieldErrors().stream()\n            .map(error -> error.getField()).distinct().sorted().toList());\n        return ResponseEntity.badRequest().body(problem);\n    }\n}',
  'Translate body-validation errors into a stable public shape and include only safe field identifiers.',
  'Context: Boot 3 MVC and Jakarta validation. This covers request-body validation exceptions, not malformed JSON or every method-validation exception; those need separate mappings.'),
s(13, 'Hard', 'Implement conditional document updates with ETags',
  'Implement PUT /documents/{id} for one strong numeric If-Match tag such as "7". Missing header returns 428; weak, unquoted, wildcard, negative, or multi-tag values return 400. Call supplied replace(id, expectedVersion, text), which atomically enforces the version and throws VersionMismatch on conflict. Map that to 412. Return 200 with the resulting DTO and quoted new version ETag. Support only this deliberately restricted tag syntax.',
  'If-Match: "7" with matching version -> 200 and ETag: "8". Stale version -> 412. Missing header -> 428.',
  'import org.springframework.web.bind.annotation.*;\nimport org.springframework.http.*;\n\nrecord DocumentDto(long id, long version, String text) {}\nrecord ReplaceDocument(String text) {}\nclass VersionMismatch extends RuntimeException {}\ninterface Documents { DocumentDto replace(long id, long expectedVersion, String text); }\n@RestController\nclass DocumentController {\n    private final Documents documents;\n    DocumentController(Documents documents) { this.documents = documents; }\n    // TODO conditional PUT\n}',
  'import org.springframework.web.bind.annotation.*;\nimport org.springframework.web.server.ResponseStatusException;\nimport org.springframework.http.*;\n\nrecord DocumentDto(long id, long version, String text) {}\nrecord ReplaceDocument(String text) {}\nclass VersionMismatch extends RuntimeException {}\ninterface Documents { DocumentDto replace(long id, long expectedVersion, String text); }\n@RestController\nclass DocumentController {\n    private final Documents documents;\n    DocumentController(Documents documents) { this.documents = documents; }\n    @PutMapping("/documents/{id}")\n    ResponseEntity<DocumentDto> replace(@PathVariable("id") long id,\n        @RequestHeader(value="If-Match", required=false) String tag, @RequestBody ReplaceDocument request) {\n        if (tag == null) throw new ResponseStatusException(HttpStatus.PRECONDITION_REQUIRED);\n        if (!tag.matches("\\\"[0-9]+\\\"")) throw new ResponseStatusException(HttpStatus.BAD_REQUEST);\n        long version;\n        try { version = Long.parseLong(tag.substring(1, tag.length() - 1)); }\n        catch (NumberFormatException ex) { throw new ResponseStatusException(HttpStatus.BAD_REQUEST); }\n        try {\n            DocumentDto result = documents.replace(id, version, request.text());\n            return ResponseEntity.ok().eTag("\\\"" + result.version() + "\\\"").body(result);\n        } catch (VersionMismatch ex) { throw new ResponseStatusException(HttpStatus.PRECONDITION_FAILED); }\n    }\n}',
  'Validate the restricted header, parse its version safely, delegate an atomic conditional write, and translate conflicts.',
  'Context: Boot 3 MVC and a Documents bean providing atomic compare-and-update semantics. Check long overflow, weak tags, comma-separated tags, and stale writes. Header checking without atomic storage enforcement is insufficient.'),
s(14, 'Medium', 'Load order summaries without N plus one queries',
  'Write a Spring Data JPA constructor projection for paid orders. Return ID, customer name, and total directly as OrderSummary, ordered by ID. Do not expose entities or trigger lazy traversal in controller serialization. Assume OrderEntity.customer is a to-one relation and total is BigDecimal.',
  'One query produces OrderSummary rows containing only the requested fields; no per-row customer lookups.',
  '// File: com/acme/orders/OrderSummary.java\npackage com.acme.orders;\npublic record OrderSummary(Long id, String customerName, java.math.BigDecimal total) {}\n\n// Repository snippet in the same package:\ninterface OrderRepository extends org.springframework.data.jpa.repository.JpaRepository<OrderEntity, Long> {\n    // TODO paidSummaries()\n}',
  '// File: com/acme/orders/OrderSummary.java\npackage com.acme.orders;\npublic record OrderSummary(Long id, String customerName, java.math.BigDecimal total) {}\n\n// File: com/acme/orders/OrderRepository.java\n// package com.acme.orders;\n// Imports: JpaRepository and Query from org.springframework.data.jpa.repository\ninterface OrderRepository extends org.springframework.data.jpa.repository.JpaRepository<OrderEntity, Long> {\n    @org.springframework.data.jpa.repository.Query("""\n        select new com.acme.orders.OrderSummary(o.id, c.name, o.total)\n        from OrderEntity o join o.customer c\n        where o.status = \'PAID\' order by o.id\n        """)\n    java.util.List<OrderSummary> paidSummaries();\n}',
  'Join the to-one relation in JPQL and instantiate the DTO directly from selected columns.',
  'Context: Boot 3 data-jpa, database, and supplied OrderEntity/Customer mappings with String status. Keep the public record in its own file. Check SQL query count and selected columns; this is a repository snippet, not a standalone main class.'),
s(14, 'Hard', 'Reserve database stock with one conditional update',
  'Implement repository and service snippets to reserve positive inventory using one conditional JPQL update. Return true only for exactly one updated row. The stock entity has id and quantity fields. Clear stale managed state after the bulk update, reject nonpositive quantities before SQL, and do not use a read-then-write race.',
  'Stock 5: reserve 3 succeeds, next reserve 3 fails, stored stock remains 2. Concurrent successful quantities never exceed available stock.',
  'import org.springframework.data.jpa.repository.*;\nimport org.springframework.data.repository.query.Param;\nimport org.springframework.stereotype.Service;\nimport org.springframework.transaction.annotation.Transactional;\n\ninterface StockRepository extends JpaRepository<Stock, Long> { /* TODO */ }\n@Service class StockService {\n    private final StockRepository repository;\n    StockService(StockRepository repository) { this.repository = repository; }\n    boolean reserve(long id, int quantity) { throw new UnsupportedOperationException(); }\n}',
  'import org.springframework.data.jpa.repository.*;\nimport org.springframework.data.repository.query.Param;\nimport org.springframework.stereotype.Service;\nimport org.springframework.transaction.annotation.Transactional;\n\ninterface StockRepository extends JpaRepository<Stock, Long> {\n    @Modifying(flushAutomatically=true, clearAutomatically=true)\n    @Query("update Stock s set s.quantity=s.quantity-:quantity where s.id=:id and s.quantity>=:quantity")\n    int reserve(@Param("id") long id, @Param("quantity") int quantity);\n}\n@Service class StockService {\n    private final StockRepository repository;\n    StockService(StockRepository repository) { this.repository = repository; }\n    @Transactional\n    public boolean reserve(long id, int quantity) {\n        if (quantity <= 0) throw new IllegalArgumentException("Invalid quantity");\n        return repository.reserve(id, quantity) == 1;\n    }\n}',
  'Validate the quantity and issue an atomic predicate-and-decrement update inside a transaction.',
  'Context: Boot 3 data-jpa and Stock entity. Clearing affects all managed entities, so use a deliberate service boundary. All stock writers must preserve the same invariant; test concurrency on the production database engine.'),
s(14, 'Hard', 'Read audit events with stable keyset pagination',
  'Implement a repository query returning the next at-most-100 events strictly after cursor (createdAt, id), ordered ascending by both fields. IDs are unique, createdAt is immutable Instant, and neither is null. Supply a PageRequest of size limit and no dynamic Sort. Reject limits outside 1..100. Do not use offset-based pagination or omit equal-timestamp ID tie-breaking.',
  'Cursor (10:00, 5) includes (10:00, 6) and (10:01, 1), excludes (10:00, 4). Return at most the requested limit without a count query.',
  'import java.time.Instant;\nimport java.util.List;\nimport org.springframework.data.domain.*;\nimport org.springframework.data.jpa.repository.*;\nimport org.springframework.data.repository.query.Param;\n\ninterface AuditRepository extends JpaRepository<AuditEvent, Long> { /* TODO */ }\n// TODO a service method next(cursorTime, cursorId, limit)',
  'import java.time.Instant;\nimport java.util.List;\nimport org.springframework.data.domain.*;\nimport org.springframework.data.jpa.repository.*;\nimport org.springframework.data.repository.query.Param;\nimport org.springframework.stereotype.Service;\nimport org.springframework.transaction.annotation.Transactional;\n\ninterface AuditRepository extends JpaRepository<AuditEvent, Long> {\n    @Query("""\n        select e from AuditEvent e\n        where e.createdAt > :time or (e.createdAt = :time and e.id > :id)\n        order by e.createdAt, e.id\n        """)\n    List<AuditEvent> after(@Param("time") Instant time, @Param("id") long id, Pageable limit);\n}\n@Service class AuditReader {\n    private final AuditRepository repository;\n    AuditReader(AuditRepository repository) { this.repository = repository; }\n    @Transactional(readOnly=true)\n    public List<AuditEvent> next(Instant time, long id, int limit) {\n        if (limit < 1 || limit > 100) throw new IllegalArgumentException("Invalid limit");\n        return repository.after(time, id, PageRequest.of(0, limit));\n    }\n}',
  'Use a lexicographic cursor predicate, fixed ordering, and a bounded first-page request.',
  'Context: data-jpa and AuditEvent(id, createdAt), plus an index on (created_at, id). This does not promise a frozen snapshot across requests when new rows are inserted; test equal timestamps and boundaries.'),
s(14, 'Hard', 'Handle optimistic version conflicts at the service boundary',
  'Implement rename for Product with an existing @Version long version field. Accept the expected client version, reject a mismatch, change the managed name, and flush before returning. Translate a concurrent JPA optimistic-lock failure into ProductConflict without retrying stale client intent. Assume non-null valid names and an existing product; the supplied repository extends JpaRepository.',
  'Matching version and no competitor -> rename succeeds. Stale version or concurrent conflicting flush -> ProductConflict and rollback.',
  'import org.springframework.stereotype.Service;\nimport org.springframework.transaction.annotation.Transactional;\n\nclass ProductConflict extends RuntimeException {}\n@Service class ProductEditor {\n    private final ProductRepository repository;\n    ProductEditor(ProductRepository repository) { this.repository = repository; }\n    // TODO rename(long id, long expectedVersion, String name)\n}',
  'import org.springframework.stereotype.Service;\nimport org.springframework.transaction.annotation.Transactional;\nimport org.springframework.dao.OptimisticLockingFailureException;\nimport jakarta.persistence.OptimisticLockException;\n\nclass ProductConflict extends RuntimeException {}\n@Service class ProductEditor {\n    private final ProductRepository repository;\n    ProductEditor(ProductRepository repository) { this.repository = repository; }\n    @Transactional\n    public void rename(long id, long expectedVersion, String name) {\n        Product product = repository.findById(id).orElseThrow();\n        if (product.getVersion() != expectedVersion) throw new ProductConflict();\n        product.setName(name);\n        try { repository.flush(); }\n        catch (OptimisticLockingFailureException | OptimisticLockException failure) {\n            ProductConflict conflict = new ProductConflict();\n            conflict.initCause(failure);\n            throw conflict;\n        }\n    }\n}',
  'Check the client version, mutate managed state, and flush so storage-level version conflicts occur within the translated boundary.',
  'Context: data-jpa, Product @Version mapping, and ProductRepository. A client precheck alone is racy; the versioned database update remains essential. A separate REST advice can map ProductConflict to the chosen HTTP contract.'),
s(15, 'Medium', 'Roll back a checked batch-import failure',
  'Implement importAll so rows are validated and stored in one transaction. The supplied Validator.check can throw checked InvalidRow. Any InvalidRow must roll back previously saved rows and reach the caller unchanged. Do not swallow it or open a separate transaction per row. Inputs are non-null and parsing is already complete.',
  'A three-row batch with an invalid third row stores no rows and throws InvalidRow.',
  'import java.util.List;\nimport org.springframework.stereotype.Service;\nimport org.springframework.transaction.annotation.Transactional;\n\nrecord Row(String value) {}\nclass InvalidRow extends Exception {}\ninterface RowValidator { void check(Row row) throws InvalidRow; }\ninterface RowStore { void save(Row row); }\n@Service class Importer {\n    private final RowValidator validator; private final RowStore store;\n    Importer(RowValidator validator, RowStore store) { this.validator=validator; this.store=store; }\n    // TODO importAll\n}',
  'import java.util.List;\nimport org.springframework.stereotype.Service;\nimport org.springframework.transaction.annotation.Transactional;\n\nrecord Row(String value) {}\nclass InvalidRow extends Exception {}\ninterface RowValidator { void check(Row row) throws InvalidRow; }\ninterface RowStore { void save(Row row); }\n@Service class Importer {\n    private final RowValidator validator; private final RowStore store;\n    Importer(RowValidator validator, RowStore store) { this.validator=validator; this.store=store; }\n    @Transactional(rollbackFor=InvalidRow.class)\n    public void importAll(List<Row> rows) throws InvalidRow {\n        for (Row row : rows) { validator.check(row); store.save(row); }\n    }\n}',
  'Place one proxy-invoked boundary around the loop and add the checked validation exception to rollback rules.',
  'Context: Boot 3 transaction manager and a RowStore participating in that same database transaction. Integration-test actual row counts after failure; mocks cannot prove rollback.'),
s(15, 'Hard', 'Transfer balances with ordered pessimistic locks',
  'Implement transfer between existing Account entities in one transaction using PESSIMISTIC_WRITE. Lock accounts in ascending ID order regardless of transfer direction, reject same account and nonpositive amount, check funds, then debit and credit. Use exact BigDecimal amounts. Account has balance(), debit(amount), credit(amount); no external effects occur in the transaction.',
  'Opposite-direction concurrent transfers acquire locks in the same order. Insufficient funds changes neither balance.',
  'import java.math.BigDecimal;\nimport jakarta.persistence.*;\nimport org.springframework.stereotype.Service;\nimport org.springframework.transaction.annotation.Transactional;\n\n@Service class Transfers {\n    @PersistenceContext EntityManager em;\n    // TODO transfer(long from, long to, BigDecimal amount)\n}',
  'import java.math.BigDecimal;\nimport jakarta.persistence.*;\nimport org.springframework.stereotype.Service;\nimport org.springframework.transaction.annotation.Transactional;\n\n@Service class Transfers {\n    @PersistenceContext EntityManager em;\n    @Transactional\n    public void transfer(long from, long to, BigDecimal amount) {\n        if (from == to || amount.signum() <= 0) throw new IllegalArgumentException("Invalid transfer");\n        Account first = em.find(Account.class, Math.min(from, to), LockModeType.PESSIMISTIC_WRITE);\n        Account second = em.find(Account.class, Math.max(from, to), LockModeType.PESSIMISTIC_WRITE);\n        if (first == null || second == null) throw new IllegalArgumentException("Missing account");\n        Account source = from < to ? first : second;\n        Account target = from < to ? second : first;\n        if (source.balance().compareTo(amount) < 0) throw new IllegalStateException("Insufficient funds");\n        source.debit(amount); target.credit(amount);\n    }\n}',
  'Validate, lock both rows in global order, identify source and target, then change managed balances.',
  'Context: data-jpa, transactional database and supplied Account entity. All competing balance writers must follow compatible locking. Stable order reduces this deadlock pattern but does not remove every possible database deadlock; test timeouts and rollback.'),
s(15, 'Hard', 'Store an order and outbox event atomically',
  'Implement place so a PurchaseOrder and an OutboxEvent are inserted in the same database transaction. Generate order and event UUIDs before persistence, use the order ID in the event, and return the order ID. Do not contact a broker inside this method. OutboxEvent(eventId, orderId, type) and PurchaseOrder(id, customerId) constructors are supplied.',
  'Commit -> one order and one unpublished outbox event. Failure persisting either -> neither remains.',
  'import java.util.UUID;\nimport jakarta.persistence.*;\nimport org.springframework.stereotype.Service;\nimport org.springframework.transaction.annotation.Transactional;\n\n@Service class OrderPlacement {\n    @PersistenceContext EntityManager em;\n    // TODO UUID place(long customerId)\n}',
  'import java.util.UUID;\nimport jakarta.persistence.*;\nimport org.springframework.stereotype.Service;\nimport org.springframework.transaction.annotation.Transactional;\n\n@Service class OrderPlacement {\n    @PersistenceContext EntityManager em;\n    @Transactional\n    public UUID place(long customerId) {\n        UUID orderId = UUID.randomUUID();\n        em.persist(new PurchaseOrder(orderId, customerId));\n        em.persist(new OutboxEvent(UUID.randomUUID(), orderId, "OrderPlaced"));\n        return orderId;\n    }\n}',
  'Create both identifiers and persist the business row plus durable publication intent in one transaction.',
  'Context: data-jpa, supplied entities/repositories, and one transaction manager. This is the write-side outbox boundary; a separate relay with retry and consumer deduplication is still needed for delivery. It does not claim exactly-once broker delivery.'),
s(15, 'Hard', 'Commit an audit record independently of a failed operation',
  'Implement two services: Withdrawal attempts the supplied Ledger.debit in its transaction; on RuntimeException it calls AuditWriter.record in REQUIRES_NEW and rethrows the original exception. Preserve the original failure even if auditing also fails, adding the audit failure as suppressed. Audit writes must use a separate Spring bean and transaction.',
  'Failed debit -> main transaction rolls back, successful audit remains committed, original debit exception reaches the caller.',
  'import org.springframework.stereotype.Service;\nimport org.springframework.transaction.annotation.*;\n\ninterface Ledger { void debit(long account, long cents); }\ninterface AuditStore { void insert(long account, String reason); }\n@Service class AuditWriter { /* TODO */ }\n@Service class Withdrawal { /* TODO */ }',
  'import org.springframework.stereotype.Service;\nimport org.springframework.transaction.annotation.*;\n\ninterface Ledger { void debit(long account, long cents); }\ninterface AuditStore { void insert(long account, String reason); }\n@Service class AuditWriter {\n    private final AuditStore store;\n    AuditWriter(AuditStore store) { this.store=store; }\n    @Transactional(propagation=Propagation.REQUIRES_NEW)\n    public void record(long account) { store.insert(account, "Withdrawal failed"); }\n}\n@Service class Withdrawal {\n    private final Ledger ledger; private final AuditWriter audit;\n    Withdrawal(Ledger ledger, AuditWriter audit) { this.ledger=ledger; this.audit=audit; }\n    @Transactional\n    public void withdraw(long account, long cents) {\n        try { ledger.debit(account, cents); }\n        catch (RuntimeException original) {\n            try { audit.record(account); }\n            catch (RuntimeException auditFailure) { original.addSuppressed(auditFailure); }\n            throw original;\n        }\n    }\n}',
  'Use a separate proxied bean for the independent audit boundary and rethrow the original operation failure.',
  'Context: transaction-capable Ledger/AuditStore and adequate connection pool. Avoid audit foreign keys or locks requiring uncommitted main-transaction rows. Inspect both transaction outcomes with a real database.'),
s(16, 'Medium', 'Validate JWT audience in a resource server',
  'Configure a JwtDecoder for issuer https://issuer.example and required audience orders-api. Preserve the standard issuer and timestamp validators and add audience validation. Trust signatures through issuer discovery/JWK configuration; never accept a token merely because its payload decodes.',
  'Valid signature, issuer, timestamps, and orders-api audience -> accepted. Wrong or missing audience -> rejected.',
  'import org.springframework.context.annotation.*;\nimport org.springframework.security.oauth2.jwt.*;\n\n@Configuration class JwtConfiguration {\n    @Bean JwtDecoder jwtDecoder() { throw new UnsupportedOperationException(); }\n}',
  'import org.springframework.context.annotation.*;\nimport org.springframework.security.oauth2.jwt.*;\nimport org.springframework.security.oauth2.core.*;\n\n@Configuration class JwtConfiguration {\n    @Bean JwtDecoder jwtDecoder() {\n        String issuer = "https://issuer.example";\n        NimbusJwtDecoder decoder = JwtDecoders.fromIssuerLocation(issuer);\n        OAuth2TokenValidator<Jwt> audience = token -> token.getAudience() != null && token.getAudience().contains("orders-api")\n            ? OAuth2TokenValidatorResult.success()\n            : OAuth2TokenValidatorResult.failure(new OAuth2Error("invalid_token", "Required audience missing", null));\n        decoder.setJwtValidator(new DelegatingOAuth2TokenValidator<>(\n            JwtValidators.createDefaultWithIssuer(issuer), audience));\n        return decoder;\n    }\n}',
  'Create a signature-verifying issuer decoder and compose audience validation with the default issuer/time validator.',
  'Context: spring-boot-starter-oauth2-resource-server and a SecurityFilterChain using oauth2ResourceServer(jwt). The issuer URL is illustrative; configure a real trusted issuer and test signed fixtures.'),
s(16, 'Hard', 'Enforce tenant ownership inside the secured service',
  'Implement DocumentReader.read with method authorization requiring documents:read scope. Obtain tenant_id from the authenticated Jwt, reject a missing or blank claim, and fetch using both tenant and ID through the supplied repository. Return 404 for a missing or other-tenant document without disclosing its existence. Never trust a tenant request parameter.',
  'Correct scope and owning tenant -> DTO. Missing scope -> access denied. Another tenant document -> 404.',
  'import org.springframework.stereotype.Service;\nimport org.springframework.security.access.prepost.PreAuthorize;\nimport org.springframework.security.oauth2.jwt.Jwt;\n\ninterface TenantDocuments { java.util.Optional<DocumentDto> find(String tenant, long id); }\nrecord DocumentDto(long id, String text) {}\n@Service class DocumentReader { /* TODO */ }\n// TODO enable method security in configuration',
  'import org.springframework.context.annotation.Configuration;\nimport org.springframework.stereotype.Service;\nimport org.springframework.security.access.AccessDeniedException;\nimport org.springframework.security.access.prepost.PreAuthorize;\nimport org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;\nimport org.springframework.security.core.context.SecurityContextHolder;\nimport org.springframework.security.oauth2.jwt.Jwt;\nimport org.springframework.web.server.ResponseStatusException;\nimport org.springframework.http.HttpStatus;\n\ninterface TenantDocuments { java.util.Optional<DocumentDto> find(String tenant, long id); }\nrecord DocumentDto(long id, String text) {}\n@Configuration @EnableMethodSecurity class MethodSecurityConfig {}\n@Service class DocumentReader {\n    private final TenantDocuments repository;\n    DocumentReader(TenantDocuments repository) { this.repository=repository; }\n    @PreAuthorize("hasAuthority(\'SCOPE_documents:read\')")\n    public DocumentDto read(long id) {\n        var authentication = SecurityContextHolder.getContext().getAuthentication();\n        if (authentication == null || !authentication.isAuthenticated()) throw new AccessDeniedException("Authentication required");\n        Object principal = authentication.getPrincipal();\n        if (!(principal instanceof Jwt jwt)) throw new AccessDeniedException("JWT required");\n        String tenant = jwt.getClaimAsString("tenant_id");\n        if (tenant == null || tenant.isBlank()) throw new AccessDeniedException("Tenant required");\n        return repository.find(tenant, id).orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND));\n    }\n}',
  'Authorize scope at the proxied service boundary, derive tenant from the validated principal, and make ownership part of the storage query.',
  'Context: Boot 3 Security 6 JWT resource server with a validated tenant claim and default SCOPE_ authority conversion. Invoke through the Spring proxy; test scope denial and cross-tenant reads. Repository implementation must constrain both columns.'),
s(17, 'Medium', 'Evict cached catalog data only after commit',
  'Implement rename and an after-commit listener. Update the supplied ProductRepository and publish ProductChanged inside the transaction. On successful commit, evict that ID from the products cache. Rollback must not evict. Use ApplicationEventPublisher and TransactionalEventListener, not a direct cache call before commit.',
  'Committed rename evicts matching ID. Rolled-back rename leaves cache unchanged. Other product keys remain.',
  'import org.springframework.stereotype.Service;\nimport org.springframework.context.ApplicationEventPublisher;\n\nrecord ProductChanged(long id) {}\ninterface ProductRepository { void rename(long id, String name); }\n@Service class CatalogEditor { /* TODO */ }\n// TODO after-commit cache listener',
  'import org.springframework.stereotype.Service;\nimport org.springframework.context.ApplicationEventPublisher;\nimport org.springframework.transaction.annotation.Transactional;\nimport org.springframework.transaction.event.*;\nimport org.springframework.cache.CacheManager;\n\nrecord ProductChanged(long id) {}\ninterface ProductRepository { void rename(long id, String name); }\n@Service class CatalogEditor {\n    private final ProductRepository repository; private final ApplicationEventPublisher events;\n    CatalogEditor(ProductRepository repository, ApplicationEventPublisher events) { this.repository=repository; this.events=events; }\n    @Transactional\n    public void rename(long id, String name) {\n        repository.rename(id, name); events.publishEvent(new ProductChanged(id));\n    }\n}\n@Service class CatalogCacheInvalidator {\n    private final CacheManager caches;\n    CatalogCacheInvalidator(CacheManager caches) { this.caches=caches; }\n    @TransactionalEventListener(phase=TransactionPhase.AFTER_COMMIT)\n    public void changed(ProductChanged event) {\n        var cache = caches.getCache("products");\n        if (cache != null) cache.evict(event.id());\n    }\n}',
  'Publish an in-process event in the write transaction and perform targeted eviction only in its after-commit phase.',
  'Context: transaction-capable repository and configured CacheManager with products cache. This addresses commit ordering, not guaranteed cross-crash delivery or every cache refill race. Distributed reliability may require durable invalidation events.'),
s(17, 'Hard', 'Implement an atomic Redis fixed-window limiter',
  'Implement allow(key, limit, windowMillis) using StringRedisTemplate and one Lua script. The first increment starts a fixed window by setting its TTL. Every request increments and is allowed only if count <= limit. Reject nonpositive limits/windows. The atomic script must not leave a newly created counter without expiry if the application dies. Do not renew TTL on every request.',
  'limit 2: first two requests true, third false. After expiry, the next request starts a new window. Existing TTL is not extended.',
  'import org.springframework.data.redis.core.StringRedisTemplate;\nimport org.springframework.stereotype.Service;\n\n@Service class RateLimiter {\n    private final StringRedisTemplate redis;\n    RateLimiter(StringRedisTemplate redis) { this.redis=redis; }\n    // TODO boolean allow(String key, long limit, long windowMillis)\n}',
  'import java.util.List;\nimport org.springframework.data.redis.core.StringRedisTemplate;\nimport org.springframework.data.redis.core.script.DefaultRedisScript;\nimport org.springframework.stereotype.Service;\n\n@Service class RateLimiter {\n    private static final DefaultRedisScript<Long> SCRIPT = new DefaultRedisScript<>("""\n        local count = redis.call(\'INCR\', KEYS[1])\n        if count == 1 then redis.call(\'PEXPIRE\', KEYS[1], ARGV[1]) end\n        return count\n        """, Long.class);\n    private final StringRedisTemplate redis;\n    RateLimiter(StringRedisTemplate redis) { this.redis=redis; }\n    public boolean allow(String key, long limit, long windowMillis) {\n        if (limit <= 0 || windowMillis <= 0) throw new IllegalArgumentException("Invalid policy");\n        Long count = redis.execute(SCRIPT, List.of(key), Long.toString(windowMillis));\n        if (count == null) throw new IllegalStateException("Missing Redis result");\n        return count <= limit;\n    }\n}',
  'Execute increment and first-use expiry together on the Redis server, then compare the returned count with the limit.',
  'Context: spring-boot-starter-data-redis and Redis with a dedicated namespaced counter key. Connection failure propagates (no silent allow). Retries after an ambiguous Redis response may count a request twice; this is a fixed window, not a sliding window.'),
s(18, 'Hard', 'Deduplicate a Kafka event in the business transaction',
  'Implement a JDBC-backed event handler. Insert a stable event UUID into processed_events(event_id UUID PRIMARY KEY) with PostgreSQL ON CONFLICT DO NOTHING. Only the winning insert adds the event amount to account_totals. Both operations must use the same transaction; missing accounts must fail and roll back the dedup insert. The Kafka listener delegates to this separately proxied handler and lets failures propagate.',
  'Redelivering the same event credits once. A failed account update rolls back its dedup marker so a later retry remains possible.',
  'import java.util.UUID;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.springframework.stereotype.Service;\n\nrecord CreditEvent(UUID eventId, long accountId, long cents) {}\n@Service class CreditHandler { /* TODO */ }\n// Listener will call handler.apply(event).',
  'import java.util.UUID;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.springframework.stereotype.Service;\nimport org.springframework.transaction.annotation.Transactional;\nimport org.springframework.kafka.annotation.KafkaListener;\n\nrecord CreditEvent(UUID eventId, long accountId, long cents) {}\n@Service class CreditHandler {\n    private final JdbcTemplate jdbc;\n    CreditHandler(JdbcTemplate jdbc) { this.jdbc=jdbc; }\n    @Transactional\n    public void apply(CreditEvent event) {\n        if (event.cents() <= 0) throw new IllegalArgumentException("Invalid credit");\n        int inserted = jdbc.update("insert into processed_events(event_id) values (?) on conflict do nothing", event.eventId());\n        if (inserted == 0) return;\n        if (jdbc.update("update account_totals set cents=cents+? where id=?", event.cents(), event.accountId()) != 1)\n            throw new IllegalStateException("Missing account");\n    }\n}\n@Service class CreditListener {\n    private final CreditHandler handler;\n    CreditListener(CreditHandler handler) { this.handler=handler; }\n    @KafkaListener(topics="credits", groupId="account-totals")\n    public void receive(CreditEvent event) { handler.apply(event); }\n}',
  'Claim the event ID and apply its effect atomically, treating a duplicate primary key as an already completed effect.',
  'Context: Boot 3 JDBC, Spring Kafka, PostgreSQL tables, CreditEvent JSON deserializer, and record acknowledgment after successful listener completion. Configure the JDBC transaction manager for @Transactional; this is not a distributed Kafka/database exactly-once guarantee. Check concurrent duplicate delivery.'),
s(18, 'Hard', 'Configure bounded asynchronous report work',
  'Configure reportExecutor with two core/max threads and queue capacity ten, rejecting excess submissions rather than growing without bound. Implement a separately managed @Async report service returning CompletableFuture<String> for the supplied Generator. Propagate failures through the future; callers must observe completion. Do not create an executor per request.',
  'Up to two active tasks and ten queued tasks; further saturated submissions are rejected. A generator failure completes its returned future exceptionally.',
  'import java.util.concurrent.CompletableFuture;\nimport org.springframework.stereotype.Service;\n\ninterface Generator { String build(long id); }\n// TODO executor configuration and @Async service',
  'import java.util.concurrent.*;\nimport org.springframework.context.annotation.*;\nimport org.springframework.scheduling.annotation.*;\nimport org.springframework.scheduling.concurrent.ThreadPoolTaskExecutor;\nimport org.springframework.stereotype.Service;\n\ninterface Generator { String build(long id); }\n@Configuration @EnableAsync class AsyncConfiguration {\n    @Bean("reportExecutor")\n    ThreadPoolTaskExecutor reportExecutor() {\n        var executor = new ThreadPoolTaskExecutor();\n        executor.setCorePoolSize(2); executor.setMaxPoolSize(2); executor.setQueueCapacity(10);\n        executor.setThreadNamePrefix("report-");\n        executor.setRejectedExecutionHandler(new ThreadPoolExecutor.AbortPolicy());\n        return executor;\n    }\n}\n@Service class AsyncReports {\n    private final Generator generator;\n    AsyncReports(Generator generator) { this.generator=generator; }\n    @Async("reportExecutor")\n    public CompletableFuture<String> build(long id) {\n        return CompletableFuture.completedFuture(generator.build(id));\n    }\n}',
  'Provide one container-managed bounded executor and invoke its named async service through a proxy.',
  'Context: Spring Boot 3 and a Generator bean. Spring initializes and destroys the executor bean. Saturation can throw TaskRejectedException at submission rather than returning a future, so handle that at the caller boundary. Test with latches, not sleeps.'),
s(19, 'Hard', 'Retry only transient idempotent WebClient reads',
  'Implement load(id) returning Mono<String> for GET /inventory/{id}. Retry only HTTP 503 up to two additional attempts with 100 ms exponential backoff; never retry other 4xx/5xx. Apply a two-second deadline to the entire pipeline including retries. Preserve final underlying failure on exhaustion. Do not subscribe or block inside the method.',
  '503, 503, 200 -> value after 3 calls. 404 -> one call and error. Total operation exceeding 2 seconds -> timeout.',
  'import reactor.core.publisher.Mono;\nimport org.springframework.web.reactive.function.client.WebClient;\n\nclass InventoryClient {\n    private final WebClient client;\n    InventoryClient(WebClient client) { this.client=client; }\n    Mono<String> load(long id) { throw new UnsupportedOperationException(); }\n}',
  'import java.time.Duration;\nimport reactor.core.publisher.Mono;\nimport reactor.util.retry.Retry;\nimport org.springframework.web.reactive.function.client.*;\n\nclass InventoryClient {\n    private final WebClient client;\n    InventoryClient(WebClient client) { this.client=client; }\n    Mono<String> load(long id) {\n        return client.get().uri("/inventory/{id}", id).retrieve().bodyToMono(String.class)\n            .retryWhen(Retry.backoff(2, Duration.ofMillis(100))\n                .filter(error -> error instanceof WebClientResponseException response && response.getStatusCode().value() == 503)\n                .onRetryExhaustedThrow((spec, signal) -> signal.failure()))\n            .timeout(Duration.ofSeconds(2));\n    }\n}',
  'Create the GET pipeline, narrowly filter retryable errors, and place the total timeout after the retry operator.',
  'Context: spring-boot-starter-webflux and a base-URL WebClient bean. Configure transport connect/response timeouts too. Use Reactor virtual-time or a controllable HTTP test server to check attempts and deadline; retries are limited to an idempotent read.'),
s(19, 'Hard', 'Propagate a stable idempotency key with OpenFeign',
  'Define an OpenFeign PaymentsClient for POST /charges and a service forwarding the caller-provided UUID idempotency key unchanged on every call. Reject null keys and nonpositive cents. Explicitly configure Retryer.NEVER_RETRY so this client never automatically retries ambiguous writes. Assume the remote service durably deduplicates by this key and returns the original result.',
  'Same caller key -> identical Idempotency-Key header on repeated requests. Timeouts propagate without an automatic second charge request.',
  'import java.util.UUID;\nrecord ChargeRequest(long cents) {}\nrecord ChargeReceipt(String id) {}\n// TODO Feign client, no-retry configuration, and service',
  'import java.util.*;\nimport feign.Retryer;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.cloud.openfeign.FeignClient;\nimport org.springframework.web.bind.annotation.*;\nimport org.springframework.stereotype.Service;\n\nrecord ChargeRequest(long cents) {}\nrecord ChargeReceipt(String id) {}\n// Keep this configuration scoped to this Feign client, outside component scanning.\nclass PaymentsFeignConfiguration {\n    @Bean Retryer retryer() { return Retryer.NEVER_RETRY; }\n}\n@FeignClient(name="payments", url="${payments.url}", configuration=PaymentsFeignConfiguration.class)\ninterface PaymentsClient {\n    @PostMapping("/charges")\n    ChargeReceipt charge(@RequestHeader("Idempotency-Key") String key, @RequestBody ChargeRequest request);\n}\n@Service class Payments {\n    private final PaymentsClient client;\n    Payments(PaymentsClient client) { this.client=client; }\n    public ChargeReceipt charge(UUID key, long cents) {\n        Objects.requireNonNull(key);\n        if (cents <= 0) throw new IllegalArgumentException("Invalid charge");\n        return client.charge(key.toString(), new ChargeRequest(cents));\n    }\n}',
  'Make the stable key an explicit service input, forward it as a header, and disable implicit retries at the client.',
  'Context: compatible Spring Cloud BOM for the chosen Boot 3 release, starter-openfeign, @EnableFeignClients, URL and finite connect/read timeouts. A header alone provides no deduplication; remote behavior is a required contract. Check requests with a stub server.'),
s(20, 'Medium', 'Verify REST validation with a focused MVC test',
  'Write a Boot 3.4+ @WebMvcTest for the supplied CustomerController from the create-customer challenge. POST a blank name and valid email, expect 400, and verify no CustomerService interaction. Disable security filters only for this isolated validation test; authentication behavior belongs in separate tests.',
  'Invalid request returns 400 and verifyNoInteractions(service) passes.',
  'import org.junit.jupiter.api.Test;\nimport org.springframework.boot.test.autoconfigure.web.servlet.*;\nimport org.springframework.test.context.bean.override.mockito.MockitoBean;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.test.web.servlet.MockMvc;\n\n@WebMvcTest(CustomerController.class)\n@AutoConfigureMockMvc(addFilters=false)\nclass CustomerValidationTest {\n    @Autowired MockMvc mvc;\n    @MockitoBean CustomerService service;\n    @Test void rejectsBlankNameWithoutCallingService() throws Exception { /* TODO */ }\n}',
  'import org.junit.jupiter.api.Test;\nimport org.springframework.boot.test.autoconfigure.web.servlet.*;\nimport org.springframework.test.context.bean.override.mockito.MockitoBean;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.test.web.servlet.MockMvc;\nimport org.springframework.http.MediaType;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;\nimport static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;\nimport static org.mockito.Mockito.verifyNoInteractions;\n\n@WebMvcTest(CustomerController.class)\n@AutoConfigureMockMvc(addFilters=false)\nclass CustomerValidationTest {\n    @Autowired MockMvc mvc;\n    @MockitoBean CustomerService service;\n    @Test void rejectsBlankNameWithoutCallingService() throws Exception {\n        mvc.perform(post("/customers").contentType(MediaType.APPLICATION_JSON)\n            .content("""\n                {"name":"  ","email":"ada@example.com"}\n                """))\n            .andExpect(status().isBadRequest());\n        verifyNoInteractions(service);\n    }\n}',
  'Load the MVC slice, replace the service with a mock, send invalid JSON content, and assert status plus absence of a business call.',
  'Context: Boot 3.4+ starter-test and validation; use the earlier customer endpoint or an equivalent supplied controller. For older Boot 3 versions use @MockBean instead of @MockitoBean. This test deliberately focuses on validation.', 'Java 17+ | Spring Boot 3.4+ / JUnit 5'),
s(20, 'Hard', 'Verify PostgreSQL uniqueness with Testcontainers',
  'Write an integration test with a PostgreSQL 16 Testcontainer, DynamicPropertySource, and JdbcTemplate. Create customer_email(email text NOT NULL UNIQUE) in @BeforeEach. Insert an email, assert a duplicate insert throws DuplicateKeyException, and verify exactly one row remains. Do not rely on H2 or a surrounding test transaction that remains aborted after the expected SQL error.',
  'First insert succeeds, duplicate is rejected by PostgreSQL, count remains 1.',
  'import org.junit.jupiter.api.*;\nimport org.springframework.boot.test.context.SpringBootTest;\nimport org.testcontainers.junit.jupiter.*;\nimport org.testcontainers.containers.PostgreSQLContainer;\n\n@SpringBootTest @Testcontainers\nclass EmailConstraintTest {\n    // TODO container, datasource properties, setup, and assertion\n}',
  'import org.junit.jupiter.api.*;\nimport static org.junit.jupiter.api.Assertions.*;\nimport org.springframework.boot.test.context.SpringBootTest;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.test.context.*;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.springframework.dao.DuplicateKeyException;\nimport org.testcontainers.junit.jupiter.*;\nimport org.testcontainers.containers.PostgreSQLContainer;\n\n@SpringBootTest @Testcontainers\nclass EmailConstraintTest {\n    @Container static PostgreSQLContainer<?> database = new PostgreSQLContainer<>("postgres:16-alpine");\n    @DynamicPropertySource static void databaseProperties(DynamicPropertyRegistry properties) {\n        properties.add("spring.datasource.url", database::getJdbcUrl);\n        properties.add("spring.datasource.username", database::getUsername);\n        properties.add("spring.datasource.password", database::getPassword);\n    }\n    @Autowired JdbcTemplate jdbc;\n    @BeforeEach void schema() {\n        jdbc.execute("drop table if exists customer_email");\n        jdbc.execute("create table customer_email(email text not null unique)");\n    }\n    @Test void rejectsDuplicateEmail() {\n        jdbc.update("insert into customer_email(email) values (?)", "ada@example.com");\n        assertThrows(DuplicateKeyException.class, () -> jdbc.update("insert into customer_email(email) values (?)", "ada@example.com"));\n        assertEquals(1, jdbc.queryForObject("select count(*) from customer_email", Integer.class));\n    }\n}',
  'Start the real database engine, wire its connection into the application test context, and exercise the actual unique constraint.',
  'Context: existing Boot application, starter-jdbc, PostgreSQL driver, starter-test, Testcontainers JUnit and PostgreSQL modules, and Docker. This test owns its isolated table; do not run it against a shared database. In a real app prefer production migrations to ad hoc schema.'),
s(21, 'Medium', 'Record operation duration on success and failure',
  'Implement MeasuredCheckout.place around supplied CheckoutWork.run. Record a checkout.duration Timer observation even if run throws, preserving the return value or original exception. Use a supplied MeterRegistry, create the timer once in the constructor, and do not add customer IDs as tags.',
  'One success plus one failure -> timer count 2; the failed operation still throws its original exception.',
  'import io.micrometer.core.instrument.*;\nimport org.springframework.stereotype.Service;\n\ninterface CheckoutWork { String run(); }\n@Service class MeasuredCheckout {\n    // TODO constructor and place()\n}',
  'import io.micrometer.core.instrument.*;\nimport org.springframework.stereotype.Service;\n\ninterface CheckoutWork { String run(); }\n@Service class MeasuredCheckout {\n    private final MeterRegistry registry; private final Timer timer; private final CheckoutWork work;\n    MeasuredCheckout(MeterRegistry registry, CheckoutWork work) {\n        this.registry=registry; this.work=work;\n        this.timer=Timer.builder("checkout.duration").register(registry);\n    }\n    public String place() {\n        Timer.Sample sample = Timer.start(registry);\n        try { return work.run(); }\n        finally { sample.stop(timer); }\n    }\n}',
  'Create one timer and stop a fresh sample in finally for each invocation.',
  'Context: Boot 3 Actuator/Micrometer and a CheckoutWork bean. Verify count on both paths with SimpleMeterRegistry. This measures synchronous completion only, not the eventual result of a returned reactive publisher.'),
s(21, 'Hard', 'Bound HTTP metric dimensions by route and outcome',
  'Implement ApiMetrics.record(route, status). Accept only route templates /orders/{id} and /customers/{id}; collapse every other string to other. Collapse status to 2xx, 4xx, 5xx, or other. Increment api.requests with only those two bounded tags. Never tag a concrete path, user ID, or exception message. Pre-register all 12 possible combinations.',
  'record("/orders/123", 200) -> route=other,status=2xx. record("/orders/{id}", 404) -> route=/orders/{id},status=4xx. No new label values are created.',
  'import io.micrometer.core.instrument.*;\nimport org.springframework.stereotype.Component;\n\n@Component class ApiMetrics {\n    // TODO pre-register counters and implement record\n}',
  'import java.util.*;\nimport io.micrometer.core.instrument.*;\nimport org.springframework.stereotype.Component;\n\n@Component class ApiMetrics {\n    private final Map<String, Counter> counters;\n    ApiMetrics(MeterRegistry registry) {\n        Map<String, Counter> values = new HashMap<>();\n        for (String route : List.of("/orders/{id}", "/customers/{id}", "other"))\n            for (String status : List.of("2xx", "4xx", "5xx", "other"))\n                values.put(route + ":" + status, Counter.builder("api.requests")\n                    .tag("route", route).tag("status", status).register(registry));\n        counters = Map.copyOf(values);\n    }\n    public void record(String route, int status) {\n        String boundedRoute = "/orders/{id}".equals(route) || "/customers/{id}".equals(route) ? route : "other";\n        String family = status >= 200 && status < 300 ? "2xx"\n            : status >= 400 && status < 500 ? "4xx" : status >= 500 && status < 600 ? "5xx" : "other";\n        counters.get(boundedRoute + ":" + family).increment();\n    }\n}',
  'Normalize inputs into small allow-listed dimensions and increment only a prebuilt counter.',
  'Context: Actuator/Micrometer. Verify at most 12 counter meters after thousands of arbitrary paths/statuses. In Spring MVC obtain the matched route template rather than raw request URI when integrating this component.'),
];
